fn check_all_lowercase(v: &Vec<char>) -> bool {
    // Must be non-empty
    if v.is_empty() {
        return false;
    }
    // Every character must be in 'a'..='z'
    v.iter().all(|&c| c.is_ascii_lowercase())
}

fn solve(input: Vec<char>) -> Vec<char> {
    if check_all_lowercase(&input) {
        vec!['a']
    } else {
        vec!['A']
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_all_lowercase() {
        assert!(check_all_lowercase(&vec!['a', 'b', 'z']));
        assert!(!check_all_lowercase(&vec![]));
        assert!(!check_all_lowercase(&vec!['A', 'b', 'c']));
        assert!(!check_all_lowercase(&vec!['a', 'b', '1']));
        assert!(!check_all_lowercase(&vec!['a', '-', 'z']));
    }

    #[test]
    fn test_solve() {
        assert_eq!(solve(vec!['a', 'b', 'c']), vec!['a']);
        assert_eq!(solve(vec![]), vec!['A']);
        assert_eq!(solve(vec!['x', 'Y', 'z']), vec!['A']);
        assert_eq!(solve(vec!['m']), vec!['a']);
        assert_eq!(solve(vec!['9']), vec!['A']);
    }
}